  'Heh...': '*唉...',
  'I made a promise to help you all the way to the Castle.': '*我答应过要一路帮你到城堡。',
  'So... I will.': '*所以...我不会食言。',
  'Just had to make my grievances known, ya know?': '*只是想发泄下不满，懂吗?',
  'A little respect goes a long way.': '*毕竟，尊重再小，影响也是深远的。',
