  'Not really worth the trouble.': '*不值得这么大费周章。',
  'Still at it, huh?': '*还在继续呢?',
  'Sorry but I\'m runnin\' low on witty comments at this point.': '*恐怕在这节骨眼上我是说不出什么幽默的评论了。',
  '...What? You want me to keep inflating your ego?': '*...哈?想让我继续吹嘘你的虚荣心?',
  'This was novel back in like, Snowdin, but now?': '*这要是在Snowdin还算新鲜，但现在呢?',
  'I don\'t know... Aren\'t you bored?': '*我真不懂了...你不无聊吗?',
  'Right.': '*算了。',
  'Wow! I am constantly astonished by your abilities!': '*哇塞!我不断在被你的本事惊到!',
  'The skill it must\'ve taken to shoot a bunch of tin cans!': '*射击一堆破铜烂铁绝对要有的高超技艺!',
  'Just, inspiring!': '*真就，太令人热血沸腾啦!',
  'Okay.': '*行了。',
  'We\'ve had our fun in this place but seriously...': '*咱们在这地方玩得挺开心，但实话说...',
  'This was a big waste of time. For both of us.': '*这太浪费时间了，对你我来说都是。',
  'Don\'t you agree?': '*同不同意?',
  'You proved you could best ASGORE a long time ago.': '*你很久以前就证明了你能够打败ASGORE。',
  'All of this... It\'s excessive, ya know?': '*这些事情...都搞得有点过头了，懂吗?',
  'So let\'s just stroll on up to the Castle now.': '*所以，咱们现在直接去城堡吧。',
  'No more unnecessary battles.': '*别再打这种没必要的战斗了。',
  'Save your energy for the fight that matters, okay?': '*为有必要的战斗省点力气，行吗?',
  'Trust me on this, buddy.': '*在这方面信我的，伙计。',
  'What are you doing back here? The exit\'s the other way, silly!': '*你在这边干什么?出口在另一边呢，呆瓜!',
  'Let\'s get going.': '*我们走吧。',
  'Howdy!': '*哈喽!',
  'You seem to be progressing well!': '*看起来你进展很顺利嘛!',
  'Not that I expected anything else.': '*我倒没指望别的。',
  'Let\'s get out there and see what this place has to offer!': '*咱们出去看看这地方都有什么东西!',
  'You think anyone still lives here?': '*你觉得还有人住在这里吗?',
  'Eh, if they do, you can handle it!': '*嗯，如果有人住这的话，你能搞定的!',
  'Let\'s get a move on, buddy!': '*咱继续走吧，伙计!',
  'Let\'s get\'cha saved!': '*来给你存个档吧!',
  'So it\'s truly just you and me in this place, huh?': '*所以这里真的只有咱俩么?',
  'Bit of an anticlimax after everything we\'ve been through.': '*在我们经历了这一切之后，倒是有点煞风景。',
  'I\'m thankful though, the Dunes were draining!': '*不过我很庆幸，沙丘快要榨干我了!',
  'Time\'s a-ticking, Clover!': '*时间不等人，Clover!',
  'Glad to see you out and about!': '*很高兴看到你成功逃出来了!',
  'Axis\' brain must be rusted through.': '*Axis的大脑肯定是全锈住了。',
  'Didn\'t take much to escape his \"trap.\"': '*没花多大功夫就逃脱了他的“陷阱”。',
  'I have a feeling you haven\'t seen the last of him, though.': '*不过，我有种感觉，你未来还会遇见他的。',
  'The lake ahead looks mighty treacherous!': '*前面的湖看起来很凶险!',
  'Let\'s take a look at what we\'re dealing with, pal!': '*看看咱们要对付的是什么东西，伙计!',
  'Look at you sailing across a blazing lake with ease!': '*看看你轻轻松松就渡过了一片炽热的湖!',
  'These robots aren\'t useless after all!': '*看来这些机器人也不是完全没用嘛!',
  'You know, it\'s kinda funny...': '*跟你说，还挺搞笑的...',
  'This bot looks like it could kick the bucket any day...': '*这个机器人看起来随时都会散架...',
  '...Yet it glided across the lava no problem.': '*...却能完好无损地穿过熔岩。',
  'Sure can\'t say the same for Martlet\'s \"sturdy\" raft, haha!': '*Martlet那“牢固”的小船就说不定了，哈哈!',
  'Further into this facility we go!': '*咱们往这个设施里边走啦!',
  'Not a fan of this area\'s bleak vibe, honestly.': '*老实说，我不喜欢这地方惨淡的氛围。',
  'I got my fill of this kinda stuff with the Ruins.': '*这种氛围我在遗迹的时候就已经受够了。',
  'Guess I\'m not freezing or choking on sand so...': '*起码我现在既没冻得要命，又没呛到沙子...',
  '...It\'s certainly been worse, haha!': '*...现在还算比之前强点，哈哈!',
  'We better get moving before this place collapses!': '*趁这地方还没塌，我们最好赶紧走!',
  'It\'s definitely seen better days!': '*之前肯定比现在强!',
  'What IS all this stuff?': '*这都是什么鬼东西?',
