  'To whom it may concern:': '*致有关人士：',
  'After building the first ball puzzle, I realized a fatal flaw in its design.': '*在建造第一个熔岩石谜题后，我意识到其设计存在一个致命错误。',
  'How was an intruder supposed to like, see it?': '*入侵者到底该怎么，呃，看见它?',
  'The puzzle was on a higher plain, out of your average monster\'s eyesight.': '*整个谜题被放在了一个更高的平面上，在一个正常怪物的视野外。',
  'If someone solved that puzzle, they must be very good at guessing.': '*如果有人解开了那个谜题，那个人肯定很擅长猜测。',
  'In any case, I have created an improved version!': '*不论如何，我建造了一个改进版!',
  'With a new vertical design, you can see what you\'re controlling!': '*有了新的垂直设计，你就能看见你在操控什么了!',
  'The parts may still get stuck though.': '*但那些零件还是可能会卡住。',
  'Please refer to my instructions back at the first puzzle if that happens.': '*如果卡住了，请回顾我第一个谜题所给的指示。',
  'Signed: Martlet of the Underground Royal Guard': '*签名：地底皇家守卫，Martlet',
