  '(Just some junk.)': '*（只是一些垃圾。）',
  '(A wooden bench.)': '*（一张木质长椅。）',
  '(A note is nailed to the kiosk post. It says,)': '*（小亭的墙上钉着一张便条。写着：）',
  '\"Hello, traveler! Due to infrequent breaks, I am prone to snoozing on the job.\"': '*“你好，旅行者!因为小憩的时间并不常有，所以我很容易会在工作时打瞌睡。”',
  'If you\'re reading this and I\'m asleep, pleeease don\'t just walk past this checkpoint!': '*如果我在你读这张便条的时候睡着了，拜托拜托不要直接路过这个检查点!',
  'That would dock my pay for sure!#Ring the bell to wake me up instead, thank you.\"': '*那绝对会导致我被扣薪水!不如按一下铃铛弄醒我，感激不尽。”',
  '- Martlet of the Underground Royal Guard Snowdin Division': '*-地底皇家守卫Snowdin分部，Martlet',
  '(An abandoned kiosk with snow slowly gathering inside.)': '*（一个被抛弃的岗亭，里面正在慢慢积雪。）',
  '(You watch as the bitter, whistling breeze rustles the notebook lying on the counter.)': '*（你看着冰冷的风吹过柜台上的笔记本，弄得纸张沙沙作响。）',
  '(There\'s a notebook on the counter, titled, \'My Puzzle Blueprints\'.)': '*（柜台上有一本笔记本，标题写着「我的谜题设计图」。）',
  '(This must be where Martlet sketches her puzzle ideas.)': '*（这绝对是Martlet构思谜题的地方。）',
  '(A container bearing a strange symbol.)': '*（有着奇怪符号的容器。）',
  '(The lid is bolted shut. It\'s impossible to open.)': '*（盖子被螺栓锁紧了。不可能打开的。）',
