  '(A painting of an unfamiliar place.)': '*（一副画着不知道哪里的画。）',
  '(Nothing special. Just a lamp.)': '*（没什么特别的。只是一盏灯。）',
  '(A lamp.)': '*（一盏灯。）',
  '(The door is jammed shut.)': '*（门被卡住了。）',
  '(Old machines.)': '*（旧机器。）',
