  'Hopeless!#Unprofessional!': '冇药可救!#不专业!',
  'It accomplished#giving me joy...#but I cannot eat#joy!': '佢畀佐我快乐...#但系快乐唔食得!',
  'Ze egg is not#alive! Well...#not anymore :/': '呢个蛋#不是活的!#再也不是了:/',
