  'If you can\'t#stand ze heat...#good!': '如果你能#忍受这个温度...#好!',
  'Natural#ingredients!#Never#substitute!': '天然成分!#从不替代!',
  'A bit of zis...#a bit of zat...': '一点呢个...#一点嗰个...',
  'C\'est croquant,#c\'est fondant...': '脆卜卜，#软淋淋...',
