  '...Almost looks like it\'s watching me.': '*...就像是在看着我一样。',
  'Not sure I like this room...': '*我不太喜欢这个房间...',
  'You... beat me up pretty b-badly, huh?': '*你...把我揍-揍得挺狠的，哈?',
  'S-Star I...': '*S-Star，我...',
  'Don\'t sweat it too much...': '*没事，别太在意了...',
  'I reckon I deserved it for the Wild East fiasco.': '*这就当做是我在狂野东方惹出来的闹剧的报应吧。',
