  'I DID IT AGAIN.#HOW.': '「我又胡言乱语了。#怎么会。」',
  'WAIT. THIS IS#YOUR DOING. OF#COURSE IT IS.': '「等等。#是你干的好事。#果然是。」',
  'DO NOT SHOCK#ME AGAIN, OKAY?': '「别再电我了，#行吗?」',
  'COULD YOU PLEASE#DROP IT?': '「你能把它#放下吗?」',
  'JUST KICK IT#INTO THE FIERY#PIT BELOW US.#SIMPLE.': '「很简单。#把它踢到#下面的火坑里#就行了。」',
  'ZBsssZ t-t-D#? d': '「ZBsssZt-t-D#?d」',
  'THAT IS ENOUGH.': '「够了。」',
  'UNBEKNOWNST TO#YOU, I BROUGHT#A BACKUP PLAN.': '「你不知道的是#我还有个#后备计划。」',
  'PORTABLE#GENERATORS#=#INFINITE BATTERY.': '「移动电源=#无限电量。」',
  'GOOD LUCK.': '「祝你好运。」',
  'SERIOUSLY???': '「认真的???」',
