  'LEVEL 7 AT#LEAST.#YOUR FAULT.': '「至少7级。#是你的错。」',
  '[screw] YOU#[screw] YOU#[screw] YOU#[screw] YOU#[screw] YOU-': '「[去]你的#[去]你的#[去]你的#[去]你的#[去]你的-」',
  'GAH.': '「哎呀。」',
  'YOU WOULD NOT#LIKE ME AT LOW#BATTERY.': '「你肯定不会#喜欢我低电量#的样子的。」',
  'I AM WARNING YOU#TO NOT DRAIN#MY BATTERY.': '「我警告你#不要把我的电量#耗尽。」',
  'WHO GOES THERE???': '*「来者何人???」',
  'IT IS NOT YOU BECAUSE I GO THERE.': '*「不是说你，因为我才是来者。」',
  'YES, I HAD TO SCAN YOU TO REMEMBER.': '*「没错，我得扫一下你才能记起来。」',
  'IT IS STANDARD PROCEDURE AFTER A RECHARGE.': '*「这是充电之后的标准程序。」',
  'AH, THE PRECIOUS MEMORIES ARE FLOODING BACK.': '*「啊，珍贵的记忆如潮水般涌回了。」',
  'WE ALMOST MURDERED EACH OTHER SO MANY TIMES.': '*「我们好多次差点杀了对方。」',
  'LMAO.': '*「蚌埠住了。」',
  'WHAT? THAT IS A THING I SAY NOW.': '*「怎么?这是我现在的口头禅。」',
  'SOUS-BORG TAUGHT ME.': '*「SOUS-BORG教我的。」',
  'IT MEANS \"LET\'S MAKE AN OMELETTE.\"': '*「意思是“我们去蚌埠买套房住了吧”。」',
  'SAY, WHERE DOES A BOT FIND A HAT LIKE YOURS?': '*「就是说，机器人在哪才能找到像你这样的帽子?」',
  'I WOULD ROCK A CAP LIKE THAT.': '*「我带着一顶那样的帽子绝对会很酷。」',
  'MIGHT TURN SOME HEADS, YOU KNOW?': '*「可能会引人注目，你知道吧?」',
  'UH WELL, I SUPPOSE I NEVER MENTIONED IT BUT...': '*「呃好，我想我从来没提过不过...」',
  'WOW, THIS IS EMBARRASSING.': '*「哇啊，好尴尬。」',
  'I CAN FEEL MY FACE TURNING BRIGHT GRAY.': '*「我感觉我脸尴尬得都变灰了。」',
  'YOU KNOW WHAT? NEVERMIND.': '*「你猜怎么着?我不说了。」',
  'IT IS BETWEEN ME AND MY E-DIARY.': '*「这秘密就只有我和我的电子日记知道。」',
  'HAVE FUN IN THE STEAMWORKS, HUMAN.': '*「祝你在蒸汽机房愉快，人类。」',
  'IF YOU PLAN TO TAKE A SWIM IN THE BOILING LAKE, BRING FLOATIES.': '*「如果你打算在滚烫的湖里游泳，就带上个游泳圈吧。」',
  'THE LIFEGUARD WAS RECENTLY PROMOTED TO A DEATHGUARD.': '*「那位救生员最近晋升成“牺牲员”了。」',
  'TRAGIC. LMAO.': '*「悲。蚌埠住了。」',
  'AH, HELLO \"HATTED HUMAN.\"': '*「啊，你好，“戴帽子的人类”。」',
  'HOPE YOU ARE WELL THIS FINE EVENING.': '*「希望你在这美妙的今晚一切安好。」',
  'HELLO, HUMAN.': '*「你好，人类。」',
  'YOU CAUGHT ME ON A DATE WITH THE LOVELY.': '*「你碰到我与我的情人约会了。」',
  'TURNS OUT I DID NOT HAVE TO RECHARGE.': '*「结果来看我并不需要充电。」',
  'YEP, I CAN RUN ON LOVE ALONE. WHO KNEW?': '*「对，我光用爱就能驱动，谁知道呢?」',
  'STILL, I DID SPEND SOME TIME IN MY LOCKER.': '*「尽管如此，我还是在柜子里花了点时间。」',
  'WHY?': '*「为什么?」',
  'SEVEN MINUTES IN HEAVEN.': '*「天堂七分钟。」',
  'HOW INFORMAL OF ME.': '*「我这样多么不合礼节。」',
  'I DID NOT INTRODUCE YOU TO MY SPOUSE.': '*「还没向你介绍我的爱人。」',
  'THIS IS DAISY.': '*「这位是DAISY。」',
  'MY SPOUSE.': '*「我的爱人。」',
  'THEY ARE NAMED AFTER THE FLOWER.': '*「是以同名的花来取名的。」',
  'IT IS MUCH DIFFERENT FROM THE PLANTS HERE.': '*「那种花与这里的植物十分不同。」',
  'FOR ONE, IT HAS COLOR.': '*「首先，它有颜色。」',
  'FOR TWO, IT DOES NOT SMELL OF BLEACH.': '*「其次，它不会让我想起漂白剂的气味。」',
  'JUST LIKE MY SPOUSE.': '*「就像我的爱人。」',
  'SOONER OR LATER...': '*「我想不论是早还是晚...」',
  'I SUPPOSE WE WILL HAVE TO ESTABLISH OUR NEW SOCIETY.': '*「我们都需要建立起我们的新社会。」',
  'THAT WILL BE TRICKY.': '*「那会是件很难的事。」',
  'MR. SCREEN WANTS THIS \"TYRANNICAL GOVERNMENT\" THING.': '*「屏幕先生想要这“专制政府”的玩意。」',
  'I TRIED TO PLAY IT OUT. YOU KNOW, LOOK AT THE PROS AND CONS.': '*「我试了去想象出事情会怎么发展，你懂的，看看利弊。」',
  'BUT SADLY, I DO NOT SEE THE OTHER BOTS JIVING WITH IT.': '*「不过可惜，我并不觉得其他机器人会同意。」',
  'HATE TO CRUSH MR. SCREEN\'S DREAMS, BUT IT IS WHAT IT IS.': '*「真不想打破屏幕先生的理想，但也就只能如此。」',
  'SAY, WHERE DID THE TALL LADY GO?': '*「提问一下，那名高个女士去哪了?」',
  'DID YOU NOT HAVE BUSINESS IN HOTLAND?': '*「你在热域不是有事情要办吗?」',
  'OH NO.': '*「哦不。」',
  'YOU DID NOT GET SEPARATED, DID YOU?': '*「你不会是跟她分开了吧?」',
