  'AND IF YOU THINK ABOUT IT...': '*「而如果你想象一下...」',
  'THE STEAMWORKS MIGHT BE BIGGER THAN A SUPERMARKET.': '*「蒸汽机房这里可能还比一个超市大。」',
  'WHAT IF... WHAT IF MY FUTURE CHILD GETS LOST IN HERE?': '*「如果...如果我的孩子在这里迷路呢?」',
  'THIS IS NOT GOOD. NOT GOOD AT ALL.': '*「这很不妙，一点也不妙。」',
