  '*BEEP BEEP*': '**哔哔*',
  'ANXIETY ZONE REACHED_': '*「已到达焦虑区_」',
  'SEARCHING FOR RATIONALE_': '*「寻找理智中_」',
  'OH, I KNOW.': '*「噢，我懂了。」',
