  'This guy means business!': '*这家伙是认真的!',
  'My husband was one hell of an engineer.': '*我丈夫是个了不起的工程师。',
  'I just wonder why he kept all this from me?': '*但我想知道他为什么瞒着我这些事?',
  'He could\'ve left me some sort of off-switch, right?': '*他本可以给我留下一个断电开关之类的，对吧?',
