  'Useful for cleaning pools of water. Even hot pools on mountaintops.': '*用于清洁水池。山顶上的热水池都行。',
  'Gold [Au]': '金[Au]',
  'The \"Au\" means that perhaps in an alternate universe, you own some.': '*“Au”是一种让人一看就能“诶呦”一叫的元素，你如果有也会叫。',
