  'guardener#says you#deserve#termination.': 'Guardener#说你犯的#是死罪。',
  'THEY KNOW.': '「都已经知道了。',
  'sooo...': '那么...',
  'ATTACK.': '「攻击。」',
  'right.': '对。',
  'CLEVERLY DONE.': '「很聪明的做法。」',
  'YOU HAVE GAINED#MY RESPECT.': '「你已经获得了#我的尊重。」',
  'BUT YOU HAVE#NOT GAINED#MY MERCY.': '「但你还没#赢得我的#仁慈。」',
  'JUST YOU #AND I AGAIN.': '「又只有咱们#两个了。」',
