  'Custom message: Trying to play video games on the job?': '*自定义消息：打算在工作时间玩电子游戏?',
  'Please report to the head office. We have a pink-colored gift for you.': '*请到总部报到。我们有一件粉色的礼物要送给你。',
  'Emergency Shutdown': '紧急关机',
  'Back': '返回',
  'Select your option.': '*请选择。',
  'Shut down all helper bots within the vicinity?': '*是否关闭附近所有助手机器人?',
  'Attempting shut down . . .': '*正在尝试关闭...',
  'ERROR: Could not complete task.': '*错误：无法完成任务。',
  'Just kidding ;)': '*开玩笑的;)',
  'Emergency shutdown complete.': '*紧急关机完成。',
  'Why did you select this option then?': '*那你为什么选了这个选项呢?',
  'Do not wander off.': '*不要四处闲逛。',
  'It\'s dangerous in here.': '*这里很危险。',
  'Let\'s look at something else, okay?': '*让我们看看别的，行吗?',
  '(No answer...)': '*（没有回应...）',
  '(You hear an organ faintly playing on the other side.)': '*（你听到另一侧隐约传来管风琴的乐声。）',
  'Are you ready to leave?': '*你准备离开了吗?',
  'Leave Dalv\'s house?': '*离开Dalv的房子吗?',
  'If that\'s what you want, I\'ll lead the way.': '*如果你要走的话，我会送你出去的。',
  'Alright, take as long as you like.': '*没关系，想休息多久就休息多久。',
  'Well... That was#something.': '好啊...#有点东西啊你。',
  'You\'re a lot#stronger than I#gave you credit#for!': '你比我想象得#强得多!',
  'Those monsters never#stood a chance#against your skill.': '那些怪物#面对你的技巧#毫无胜算。',
  'What\'s with that#face?': '你那是什么#表情?',
  'Don\'t even think#about killing me#too.': '别想着把我#也杀了。',
  'Remember, I\'m the#one keeping you#alive.': '记住，你能活到#现在全是我的#功劳。',
  'Your life is#in my hands.': '你的命可是#在我手掌心#握着呢。',
  'Don\'t worry, I#won\'t judge you#for your actions.': '别担心，我不会#批判你的#所作所为。',
  'Friends don\'t judge#each other, right?': '朋友间是#不会互相#批判的，对吧?',
  'I have your#back and you\'ve#got mine.': '我是你坚实的#后盾，你也是#我的。',
  'So let\'s get#out of here,#okay pal?': '那么让我们#离开这吧，#好吗，伙计?',
  'Result:': '结果：',
  'I messed up, miscalculated,   something.': '我搞砸了，Axis...Axis很危险。',
  'Axis... Axis is dangerous.': '不知道是我算错了，还是怎么。',
  'I must have overshot the variables,# all I wanted was apprehension.': '我原本只是想让Axis抓住人类，但我肯定把某些变量写大了。',
  'The human who almost hurt my   child, I told Axis to track   them down.': '那个差点伤到我孩子的人类，我让Axis去追捕他。',
  'I know I should\'ve stayed to comfort#Kanako and tend to the resident who#was hurt but...': '我知道我应该留下来安慰Kanako，照顾受伤的居民，但...',
  '...I had a tool that could stop the human\'s crusade, so I tried.': '...我有工具能阻止人类继续前进，所以我就试着做了。',
  '...In a flash, Axis left me.   Bolted for Waterfall.': '...转眼间，Axis就扔下我，冲向了瀑布。',
  'By the time I tracked him down... it was too late.': '等我追上他的时候...一切都为时已晚。',
  'I\'ll never forget the scene laid before me.': '我永远都不会忘记我面前的那一幕。',
  'Part of me wanted to quit everything that instant but...': '我确实有点想立刻放弃一切，但...',
  '...This outcome was earned,   was it not?': '...这只是他罪有应得，不是吗?',
  'Axis soon contained the subject and... hid the evidence.': 'Axis很快就控制住了攻击对象，然后...藏匿了证据。',
  'There was some property damage but#I\'m sure it won\'t come back to me...#I hope.': '虽然损失了财产，但我这样就能确定它不会回来指认我...至少我希望是这样。',
  'In any case... I now have a   human SOUL in my possession.': '无论如何...我现在拥有了一个人类的「灵魂」。',
  'I do not know exactly what I should#do with it but the power that rests#within it is...': '我不知道该怎么处理它，但它蕴含的力量...',
  'Well, let\'s just say I\'m not  donating it to Asgore like all  the others. Not yet.': '这么说吧，我不会从众把它捐给Asgore。至少现在还不会。',
  'As for Axis, today\'s actions were excessive, but the potential is astounding.': '至于Axis，他今天的行为有些太过了，但其潜力还是惊人的。',
  'With more work, Axis can be the future, I\'m sure of it.': '随着工作进行，Axis可以成为未来，我对此深信不疑。',
  'Anyway, I need to sleep.': '无论如何，我需要去补充睡眠了。',
  'Though something tells me that  will be difficult to do for a  while.': '尽管我觉得我得失眠一段时间了。',
  'DONE': '完成',
  '(A presence is cowering behind the storage cabinet.)': '*（有谁正蜷缩在储物柜后面。）',
  '(But it won\'t budge.)': '*（但它不肯挪地方。）',
  '(You notice wall cracks peeking out from behind the cabinet.)': '*（你注意到墙上的裂缝从橱柜后面露了出来。）',
  '(Move it?)': '*（要挪开吗?）',
