  'I read something in a book once.': '*我在一本书里读到过一句话。',
  'It said, \"If life comes at you too fast, press X and take it slow.\"': '*写道：“如果生活过的太快，按下X键，慢慢来。”',
  'Whatever that means.': '*管它什么意思呢。',
  'You know, I read something else in that same book.': '*你知道吗，我在那本书里还读到了另一句话。',
  'It said, \"Eat food to stay strong and healthy!\"': '*写道：“吃点美食，强身健体!”',
