  'A': '*啊',
  'I\'m really sorry about the pops Starlo.': '*关于那些冰棒，Starlo我很抱歉。',
  'When I see them... It\'s like a demon takes over.': '*我看到它们的时候...感觉就像是被恶魔附身了。',
