  'Loool worth it.': '*笑死，值了。',
  'Those pops were delicious.': '*那些冰棒很好吃。',
  'What are YOU looking at?!': '*你看什么呢?!',
  'Th.i>s is- my#f-f-favorite shoOw/': '这>是-我最#喜-喜欢的节目/',
  '/NeEd s[ome#Maint/enan-ce . ,': '/需[要维-/修.,',
  'T/Time to;?#Go on coMmercial#break. ... .': '到/到广告#时间了.....',
  'What are you#staring at?': '你盯着啥看呢?',
  'There\'s nothing#on yet!': '现在还没有#节目呢!',
  'Oh! Check#this out!': '噢!#看看这个!',
  'Here comes the#best part!': '这可是#最棒的部分!',
  'Am... Am I#boring you?': '我...我让你觉得#无聊了吗?',
  'Hey, buddy!#I\'m still here!': '嘿，伙计!#我还在这呢!',
  'Just what#I needed!': '这就是我#想要的!',
  'Whoa, hey!#I\'m picking#something up!': '哇，嘿!我接收到了#什么东西!',
  'They\'re good#where they are!': '他们在那里#很好!',
  'Hey, don\'t ruin#my electrical#flow!': '嘿，别破坏#我的电流!',
  'Don\'t touch that#dial! Seriously,#I\'ll hurt you.': '别碰那个#调谐拨盘!#我会伤到你的!',
  'I live life in#glorious standard#definition!#Nothing better!': '我活在光荣的#标准定义里!#没有什么比这#更好!',
