  'Also, Mew mew doesn\'t \"shoot bullets\", she spreads joy.': '*还有啊，喵亲不是在“发射子弹”，是在散播快乐。',
  'It\'s so obvious they haven\'t studied the deep lore like I have.': '*很明显，他们没我研究得这么深。',
  'You should come over sometime.': '*你也应该过来玩玩。',
  'We could play a co-op game!': '*你来了我们就可以玩双人合作游戏了!',
