  'How exciting! Here\'s a pen!': '*我太激动了!给你一支笔!',
  '(You make a few scribbles on one of the fellow\'s needles.)': '*（你在这家伙的一根针上涂鸦了几笔。）',
  'Oh boy!': '*哦天哪!',
  'Hope you don\'t mind if I sell that needle online!': '*希望你不介意我把这根刺在网上卖掉!',
  'Ta-ta!': '*锵锵!',
  'Boo-hoo.': '*哦-吼。',
  'Good luck with the new job! Ah ha!!': '*祝你新工作顺利!啊哈!!',
  'Why if it isn\'t the Deputy!': '*这不是副警长吗!',
