  'You\'re Star\'s right-hand man, correct?': '*你是Star的副手，对吧?',
  'If you see him, tell him we all miss his leadership!': '*如果你见到他了，记得告诉他，我们都很想念他的领导力!',
  'That we do!': '*真的很想念!',
  'Hey Clover.': '*嘿Clover。',
  'Sorry we kinda ruined your fun.': '*抱歉，我们有点毁了你的兴致。',
