  'Anyway... I feel bad about the whole thing.': '*但不管怎样...我还是对这整件事感觉很糟糕。',
  'Need to talk to Star about it as soon as possible.': '*我得尽快跟Star谈谈这件事。',
  'The others needed a little more time.': '*其他人还需要一段时间缓缓。',
  'I might\'ve... snuck away while they were occupied.': '*我可能会...趁他们忙着的时候溜走吧。',
  'It\'s what I do best! Heh heh...': '*这是我最擅长的!嘿嘿...',
  'I won\'t blame you if you wanna ditch this town.': '*你想离开小镇的话，我是不会怪你的。',
