  'They never set foot on these sands.': '*他们从来没有踏足过这片沙丘。',
  'All that to say, I\'m glad you did.': '*总而言之，我很高兴你到这里来了。',
  'My name is Ceroba.': '*我叫Ceroba。',
  'Ceroba': '★■■Ceroba■',
