  'They\'re a bit too... rowdy for my taste.': '*我觉得他们对我来说有点...太吵闹了。',
  'May I ask your name?': '*我可以知道你的名字吗?',
  'Welcome to the Underground, Clover.': '*欢迎来到地底，Clover。',
  'Your attire is surprising, I must say.': '*我不得不说，你的穿着很让我惊讶。',
  'But um... I won\'t press you on the matter.': '*但是...我不会强迫你做什么事的。',
