  'Maybe you should entertain him a bit; roll with his punches.': '*也许你应该顺着他的意来，让他开心开心。',
  'I\'ll see what I can do about allowing you to leave.': '*我之后也会想想办法让他放你走的。',
  'I know of a safe path to Hotland through the...': '*我认识一条通往热域的安全的路，就在...',
