  'You see, I\'ve heard you\'ve been up to no good.': '*要知道，我听说你未曾有过善行。',
  'You\'ve been mozyin\' \'round...': '*你四处徘徊...',
  '...Terrorizin\' the nice folk of this underground settlement.': '*...让这个地底安家之所的良民们身陷恐怖...',
  'You\'re an outlaw.': '*你是个法外狂徒。',
  'My job...': '*我的职责...',
