  'Thanks for letting me feel cool for a short moment.': '*谢谢你让我暂时冷静了一下。',
  'Star! Everyone\'s evacuated!': '*Star!每个人都撤离了!',
  'Why are you still here? I told you to-': '*你怎么还在这?我不是让你-',
