  'Th... thanks... for playing a... along all these... years.': '*谢...谢谢你...这么多年一直...陪着我...',
  'Now... d... do what\'s right.': '*现在...去做正确的事吧。',
  'Deliver...': '*伸张...',
  'J-Justice.': '*正-正义。',
  'Huh? Hang on, I think someone\'s coming this way.': '*嗯?等等，好像有谁过来了。',
  'Guys! Looky here!': '*大伙儿!快来看啊!',
  'Someone new has stumbled into our humble town.': '*我们的小破镇来了两个新面孔。',
