  'I can assure you we are a delight to be around.': '*别害怕，我向你保证，你能遇到我们是件好事。',
  'Nothing you can\'t handle I\'m sure.': '*这样就没有你们解决不了的问题了。',
  'Why do you two insist on scaring away every monster you meet?': '*你们两个干嘛非要把遇到的每一个怪物都吓跑?',
