  'Mooch': 'Mooch',
  'Never!': '*底线!',
  'Um, well, it was a pleasure to meet you four but...': '*呃，那个，很高兴见到你们，不过...',
  'We\'ll be going now-': '*我们得走-',
  'Hold it right there, missy.': '*等一会儿，小姐。',
  'Are my pals givin\' you trouble?': '*我的朋友给你们添麻烦了吗?',
  'Come now...': '*得啦...',
