  'The name\'s North Star. I run this town.': '*我叫NorthStar，是这座小镇的管理者。',
  'North Star': '★■■NorthStar■■■■■■■■■■■',
  'Not alone, of course.': '*当然了，不止我一个人。如你所见，我们是一个团队。',
