  'Sneakiness!': '*S代表敏捷（Sneakiness）!',
  'T': '★T■■■■■▲▲▲▲▲▲▲▲▲■▼',
  'Toughness!': '*T代表坚韧（Toughness）!',
  'Y': '★Y■■■■■▲▲▲▲▲▲▲▲▲▲▲▲■▼',
  'Youthfulness!': '*Y代表青春（Youthfulness）!',
  'J': '★J■■■■■▲▲▲▲▲▲▲■▼',
  'Justice!': '*J代表正义（Justice）!',
  'The J is silent.': '*J不发音。',
  'Anyway': '*那么，',
  'Now that we\'re introduced...': '*我们介绍完自己了...',
  'I\'d be glad to give you and yer buddy a tour-': '*我很乐意带你和你的搭档参观一下-',
  'Yer buddy...': '*你的搭档...',
  'Are they a... HUMAN?': '*是个...「人类」吗?',
  'Well... I won\'t say no?': '*好吧...这我没法否认。',
  'I knew it!': '*我就知道!',
