  'Don\'t \"Feathers\" me!': '*别叫我“小羽毛”!',
  'You\'re speaking to Martlet of the Royal Guard!': '*跟你讲话的可是皇家守卫Martlet!',
  'I can and will report you to King ASGORE for this abrasive behavior!': '*我可以-而且马上就要把你们这种粗鲁的行为上报给ASGORE国王!',
  'Ye\'re Royal Guard?': '*你是皇家守卫?',
  'That\'s funny, \'cuz I don\'t see anythin\' to indicate that.': '*呵，有点意思，我可完全没看出来啊。',
  'No armor? Weapon? Badge?': '*盔甲、武器、徽章，啥都没有?',
  'I... left it all at my post in Snowdin!': '*我...把这些都落在我Snowdin的哨站了!',
  'Please, don\'t bother trying to fool us.': '*拜托，差不多得了吧，别想耍我们。',
  'He\'s right.': '*可不是嘛。',
  'I am truly sorry \'bout this, I really am.': '*我对此深表歉意，真的。',
  'But business is business.': '*不过，事该办还是得办。',
  'Together, we\'ll be the Feisty SIX!': '*有了Clover，我们就变成活力「六」人帮了!',
  'The alliteration...': '*变拗口了啊...',
