  'Clover, come on.': '*Clover，别这样。',
  'Is this about that letter you received in the Steamworks?': '*你是看到蒸汽机房的那封信了吗?',
  'It\'s gotta be a trap.': '*那肯定是个陷阱。',
  'You\'re seriously gonna fall for something so obvious?': '*你真的会被这么明显的事情给骗到吗?',
  'That bird never got you anywhere.': '*那只鸟从来就没把你带到哪里去过。',
  'You know who did? Me! Your best friend!': '*你知道是谁把你带过来的吗?是我!你最好的朋友!',
  'How many times have I saved your life? Huh?': '*我救过你的命多少次了?嗯?',
  'All Martlet\'s done is put it in danger!': '*而Martlet所做的一切都只会让你越来越危险!',
  'Alright, fine!': '*好吧，随便吧!',
  'If this is what you think is worth your time then I... trust you.': '*如果你觉得这值得你花时间，那么我...相信你。',
  'What else would a friend do, after all?': '*毕竟，朋友还能做什么呢?',
  'Just don\'t say I didn\'t warn you...': '*只是别说我没警告过你...',
  'Why?': '*为什么?',
  'Heh, I sure heard#that!': '嘿，我肯定听过这句!',
  'But I don\'t wanna#hear it again, okay?': '但我不想再听一遍了，#好吧?',
  'This thing hates#noise, right?': '这东西讨厌噪声，#对吧?',
  'Use that fact to#your advantage!': '把这个特点#变成你的优势!',
  'Quite the permanent#solution, eh?': '真是一劳永逸的#解决方案啊，对吧?',
  'Too bad I can#undo it, haha!': '只可惜我能复原这一切，#哈哈!',
  'This loner packs#a punch!': '这个独来独往的家伙#下手真重!',
  'Nothing you can\'t#handle, though!': '不过你肯定能解决的!',
  'Last time I checked,#no one likes a fried#human.': '据我所知，#没人喜欢油炸人类。',
  'Get back out there!': '回到那边去!',
  'Blah blah blah,#what a whiner!': '布拉布拉布拉，#真是个爱发牢骚的人!',
