  'Talk about over the#top...': '真是言过其实...',
  'Let\'s show this#showoff who\'s boss!': '给他看看#谁才是老大!',
  'I can\'t say I blame#you for dying, honestly.': '老实说，#这次你死了我不能怪你。',
