  'Nice shootin\'!': '*漂亮!',
  'I\'d say ye\'re a natural.': '*我得说你很有天赋。',
  'I\'m impressed, kid!': '*我很佩服你，孩子!',
  'It\'s alright, partner.': '*没关系，搭档。',
  'Try again!': '*再试试!',
  'Uh... actually that\'s good!': '*呃...实际上这很棒!',
  'Intimidation of yer opponent can decrease their focus!': '*恐吓对手会降低他们的注意力!',
  'Good thinkin\', Clover!': '*好主意，Clover!',
  'Let\'s practice yer shootin\' now.': '*现在我们来练习射击。',
  'Eh... what?': '呃...什么?',
  '(Visual embarrassment)': '（肉眼可见的尴尬）',
  'Alright, h-here goes#nothing.': '没错，#没-没什么的。',
  'Yeah...': '是啊...',
  'I know... sorry...': '我知道的...#抱歉...',
  'D-Don\'t mind me.': '不-不用管我。',
  'I can do this...': '我能做到的...',
  'S-Sorry human.': '抱-抱歉人类。',
  'Oh...': '哦...',
  'I deserve this...': '我活该...',
  'Here...': '送...',
  'Here you go!': '送给你!',
  'Gosh, hun.#What are you on#about?': '天哪，亲爱的。#你在说什么?',
  'Do you really mean#that hun?': '你是认真的吗，#亲爱的?',
  'Gosh, you\'ve made me#the happiest florist#around town!': '天哪，你让我成为了#镇上最快乐的#花商!',
  'About what I#expected...': '和我预料的#差不多...',
  'Oh, come now,#deary.': '哦，来吧，#亲爱的。',
  'I bet my flowers#would look very#pretty on your hat!': '我的花戴在#你的帽子上#一定很漂亮!',
  'I spend every#day to its#fullest!': '我把每一天都#过得很充实!',
  'Would you like#any flowers my#dear?': '亲爱的，#你要花吗?',
  'Sharing with others#is a great way#to show friendship!': '与他人分享是#表达友谊的#好方法!',
  'Aren\'t flowers just#magnificent?': '花儿不是#很漂亮吗?',
  'It\'s never too late#to accept a sign#of friendship, you#know.': '接受友谊的象征#永远都不迟，#你懂的。',
  'I...I\'m okay.': '我...我还好。',
  'Better than yours.': '比你的强。',
  'Pah! Don\'t I know#it!': '哼!难不成我#还能不知道?',
  'Ooo, edgy.': '唔，太前卫了。',
  'I don\'t know,#CAN YOU?': '我不确定，#你能接住吗?',
  'Come on, where\'d#you learn to#insult?': '拜托，你从哪#学来的侮辱人?',
  'SORRY ABOUT THAT!!!#Haha.': '抱歉啦!!!#哈哈。',
  'Flowers make a#monster stronger!': '花使怪物#更强大!',
  'If you want a flower#from me, you gotta#prove yourself!': '如果你想要我送你#一朵花，你得#证明你自己!',
  'Flowers are great!#Orange, blue, yellow...#gotta love \'em!': '花真的很好!#橙色，蓝色，黄色...#你会喜欢的!',
  'My flowers are top#of the line!': '我的花儿#可是极品!',
  'You\'re kind of#a jerk, you know that?': '你真是个混蛋#你知道吗?',
  'Just gotta hold#on.': '只要坚持住就好。',
  'Do you have what#it takes to be#among ze greats?': '畀我看看你#有冇能力成为#特级厨师?',
  'Tell me, how does#one cook zis#brittle spheroid?': '话畀我知，#呢个容易碎#的椭球体点做#先可以好吃?',
  'What ez ze next#step, hm?': '下一步系咩?',
