  'You\'re a       #good sing...er...': '你真是个#优秀的#歌...手...',
  '*YAWN*': '*哈欠*',
  'I like that#song...': '我喜欢这首歌...',
  'Know anything#more upbeat?': '还有比这更#乐观的吗?',
  'I see what#you\'re doing.#It\'s not gonna#work!': '我知道你在#干什么。#这行不通的!',
  'You\'re not the#boss of me.': '你又不是#我老板。',
  'Yeah, yeah,#don\'t talk to#strangers.': '啊，对，#不要和陌生人讲话。',
  'You sound like#my parents!': '你怎么跟我爸妈#一个样!',
  'Nice try.': '想得美。',
  'I\'m...#getting...#sleepy?': '我...有点...#困了?',
