  'No need to be so#crass.': '没必要这么粗鲁。',
  '*Snore*': '*哈欠*',
  'Zzzzz... noodles... zzz': 'Zzzzz...#面条...zzz',
  'When you have#friends, you#don\'t need sleep!': '当你有朋友的#时候，你不需要#睡觉!',
  'We\'re gonna stay#up all night#chatting!': '我们要聊上#一整晚!',
  'We\'re starting a#night owl club.': '我们要成立个#夜猫子俱乐部。',
