  'KNOW CONE SING HIS#FAMOUS LULLABY!': 'KNOWCONE唱他#著名的摇篮曲!',
  'KNOW CONE WILL LET#TOT SLEEP AT ALL COSTS!': 'KNOWCONE会不惜#一切代价让TOT#睡觉!',
  'KNOW CONE SHOW TOT#FLAME! TOT WILL LIKE!': 'KNOWCONE#给TOT看火!#TOT会喜欢的!',
